"""gen_launchers.py - generate Tools/launchers/*.ps1 from config.json (v5).

No hardcode: all ports/paths from config. Works for N agents (1-10).
Usage: python Tools/gen_launchers.py [--config PATH]
"""
from __future__ import annotations

import argparse
import json
import pathlib
import sys

HERE = pathlib.Path(__file__).resolve().parent
ROOT = HERE.parent
sys.path.insert(0, str(ROOT))
from Core.config import load as load_config  # noqa: E402


def _ps_header(name: str, desc: str) -> str:
    return (
        "# " + name + " - " + desc + "\n"
        "# AUTO-GENERATED by Tools/gen_launchers.py. Do not edit by hand.\n"
        "# Regenerate: python Tools/gen_launchers.py\n"
        "$ErrorActionPreference = \"Continue\"\n"
        "$Root = Split-Path -Parent $PSScriptRoot\n"
        "$CfgFile = Join-Path $Root \"config.json\"\n"
        "if (-not (Test-Path $CfgFile)) { Write-Host \"config.json not found: $CfgFile\" -ForegroundColor Red; exit 1 }\n"
        "$Cfg = Get-Content $CfgFile -Raw | ConvertFrom-Json\n"
        "$env:JEWAI_CONFIG = $CfgFile\n"
        "function Log($m) { Write-Host (\"[\" + (Get-Date -Format \"HH:mm:ss\") + \"] \" + $m) }\n"
    )


def gen_start_all(cfg):
    lines = [_ps_header("start-all.ps1", "start Mainframe + all agents + all Chrome")]
    lines.append("Set-Location $Root")
    lines.append("Log \"start-all: root=$Root\"")
    lines.append("python Tools\\boot.py --all")
    lines.append("Log \"start-all: done\"")
    return "\n".join(lines) + "\n"


def gen_stop_all(cfg):
    lines = [_ps_header("stop-all.ps1", "stop all agents + Chrome (graceful)")]
    lines.append("Set-Location $Root")
    lines.append("Log \"stop-all: root=$Root\"")
    lines.append("$agents = Get-CimInstance Win32_Process -Filter \"Name='python.exe' OR Name='pythonw.exe'\" |")
    lines.append("  Where-Object { $_.CommandLine -like \"*Bridge\\run.py*\" -and $_.CommandLine -like \"*$Root*\" }")
    lines.append("if ($agents) { Log \"agents: $($agents.Count)\"; $agents | ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue } }")
    lines.append("$letters = @($Cfg.letters)")
    lines.append("foreach ($L in $letters) {")
    lines.append("  $prof = Join-Path $Root ('Profiles\\' + $L + '\\chrome')")
    lines.append("  $ch = Get-CimInstance Win32_Process -Filter \"Name='chrome.exe'\" | Where-Object { $_.CommandLine -like \"*$prof*\" }")
    lines.append("  if ($ch) { Log \"chrome-$L graceful: $($ch.Count)\"; $ch | ForEach-Object { $p = Get-Process -Id $_.ProcessId -ErrorAction SilentlyContinue; if ($p) { $p.CloseMainWindow() | Out-Null } } }")
    lines.append("}")
    lines.append("Log \"stop-all: done\"")
    return "\n".join(lines) + "\n"


def gen_start_channel(cfg, L):
    ch = cfg["channels"][L]
    lines = [_ps_header("start-" + L + ".ps1", "start agent " + L + " + Chrome " + L)]
    lines.append("Set-Location $Root")
    lines.append("Log \"start-" + L + ": agent=" + str(ch["agent"]) + " cdp=" + str(ch["cdp"]) + "\"")
    lines.append("python Tools\\launcher.py --channel " + L)
    lines.append("python Bridge\\run.py --channel " + L + " --once")
    return "\n".join(lines) + "\n"


def gen_stop_channel(cfg, L):
    lines = [_ps_header("stop-" + L + ".ps1", "stop agent " + L)]
    lines.append("Set-Location $Root")
    lines.append("$proc = Get-CimInstance Win32_Process -Filter \"Name='python.exe' OR Name='pythonw.exe'\" | Where-Object { $_.CommandLine -like \"*Bridge\\run.py*--channel " + L + "*\" }")
    lines.append("if ($proc) { $proc | ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }; Log \"agent " + L + " stopped\" }")
    lines.append("  $prof = Join-Path $Root ('Profiles\\' + $L + '\\chrome')")
    lines.append("$ch = Get-CimInstance Win32_Process -Filter \"Name='chrome.exe'\" | Where-Object { $_.CommandLine -like \"*$prof*\" }")
    lines.append("if ($ch) { $ch | ForEach-Object { $p = Get-Process -Id $_.ProcessId -ErrorAction SilentlyContinue; if ($p) { $p.CloseMainWindow() | Out-Null } }; Log \"chrome " + L + " closed\" }")
    return "\n".join(lines) + "\n"


def gen_restart_channel(cfg, L):
    lines = [_ps_header("restart-" + L + ".ps1", "restart agent " + L)]
    lines.append("Set-Location $Root")
    lines.append("Log \"restart-" + L + "\"")
    lines.append("& (Join-Path $PSScriptRoot \"stop-" + L + ".ps1\")")
    lines.append("Start-Sleep -Seconds 1")
    lines.append("& (Join-Path $PSScriptRoot \"start-" + L + ".ps1\")")
    return "\n".join(lines) + "\n"


def gen_server_start(cfg):
    lines = [_ps_header("server-start.ps1", "start Mainframe server only")]
    lines.append("Set-Location $Root")
    lines.append("$port = " + str(cfg["chat_port"]))
    lines.append("$busy = $false")
    lines.append("try { $busy = (Test-NetConnection -ComputerName 127.0.0.1 -Port $port -InformationLevel Quiet -WarningAction SilentlyContinue) } catch {}")
    lines.append("if ($busy) { Log \"mainframe already on $port\"; exit 0 }")
    lines.append("Start-Process pythonw -ArgumentList @(\"Mainframe\\server.py\") -WorkingDirectory $Root -WindowStyle Hidden")
    lines.append("Log \"mainframe starting on $port\"")
    return "\n".join(lines) + "\n"


def gen_server_stop(cfg):
    lines = [_ps_header("server-stop.ps1", "stop Mainframe server")]
    lines.append("$port = " + str(cfg["chat_port"]))
    lines.append("$proc = Get-NetTCPConnection -LocalPort $port -State Listen -ErrorAction SilentlyContinue | Select-Object -ExpandProperty OwningProcess")
    lines.append("if ($proc) { Stop-Process -Id $proc -Force -ErrorAction SilentlyContinue; Log \"mainframe stopped\" } else { Log \"mainframe not running\" }")
    return "\n".join(lines) + "\n"


def gen_shortcut(cfg):
    lines = [_ps_header("create-shortcut.ps1", "create desktop shortcut")]
    lines.append("$desktop = [Environment]::GetFolderPath('Desktop')")
    lines.append("$lnk = Join-Path $desktop 'JewAI.lnk'")
    lines.append("$wsh = New-Object -ComObject WScript.Shell")
    lines.append("$sc = $wsh.CreateShortcut($lnk)")
    lines.append("$sc.TargetPath = \"$env:SystemRoot\\System32\\WindowsPowerShell\\v1.0\\powershell.exe\"")
    lines.append("$sc.Arguments = '-NoProfile -ExecutionPolicy Bypass -WindowStyle Minimized -File \"' + $PSScriptRoot + '\\start-all.ps1\"'")
    lines.append("$sc.WorkingDirectory = $PSScriptRoot")
    lines.append("$sc.Save()")
    lines.append("Write-Host \"Shortcut created: $lnk\"")
    return "\n".join(lines) + "\n"


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--config", default=None)
    a = ap.parse_args()
    cfg = load_config(a.config)
    raw = json.loads(pathlib.Path(a.config or cfg.root / "config.json").read_text(encoding="utf-8"))

    out_dir = cfg.root / "Tools" / "launchers"
    out_dir.mkdir(parents=True, exist_ok=True)

    letters = list(raw.get("letters", []))
    files = {
        "start-all.ps1": gen_start_all(raw),
        "stop-all.ps1": gen_stop_all(raw),
        "server-start.ps1": gen_server_start(raw),
        "server-stop.ps1": gen_server_stop(raw),
        "create-shortcut.ps1": gen_shortcut(raw),
    }
    for L in letters:
        files["start-" + L + ".ps1"] = gen_start_channel(raw, L)
        files["stop-" + L + ".ps1"] = gen_stop_channel(raw, L)
        files["restart-" + L + ".ps1"] = gen_restart_channel(raw, L)

    for name, content in files.items():
        (out_dir / name).write_text(content, encoding="utf-8-sig")
    print("generated %d files in %s" % (len(files), out_dir))
    return 0


if __name__ == "__main__":
    sys.exit(main())